<?php
require_once __DIR__.'/../core/Auth.php';require_once __DIR__.'/../core/Database.php';require_once __DIR__.'/../core/Response.php';Auth::requirePermission('hr_kpi.manage');$pageTitle='قالب‌های ارزیابی KPI';
$forms=Database::fetchAll('SELECT f.*,GROUP_CONCAT(t.title ORDER BY ft.sort_order SEPARATOR "، ") template_titles FROM hr_kpi_forms f LEFT JOIN hr_kpi_form_templates ft ON ft.form_id=f.id LEFT JOIN hr_kpi_templates t ON t.id=ft.template_id GROUP BY f.id ORDER BY f.id');
if($_SERVER['REQUEST_METHOD']==='POST'){if(!Auth::verifyCsrf($_POST['csrf_token']??'')){http_response_code(419);exit('درخواست نامعتبر است.');}$action=$_POST['action']??'';try{if($action==='template'){$id=(int)($_POST['id']??0);$code=strtoupper(preg_replace('/[^A-Z0-9_]/','',$_POST['code']??''));if($id)Database::execute('UPDATE hr_kpi_templates SET title=?,category=?,role_key=?,department=?,description=?,active=?,sort_order=?,updated_at=NOW() WHERE id=?',[trim($_POST['title']),trim($_POST['category']??''),trim($_POST['role_key']??''),trim($_POST['department']??''),trim($_POST['description']??''),isset($_POST['active'])?1:0,(int)($_POST['sort_order']??0),$id]);else Database::execute('INSERT INTO hr_kpi_templates(title,code,category,role_key,department,description,active,sort_order,created_at,updated_at) VALUES (?,?,?,?,?,?,?, ?,NOW(),NOW())',[trim($_POST['title']),$code,trim($_POST['category']??''),trim($_POST['role_key']??''),trim($_POST['department']??''),trim($_POST['description']??''),isset($_POST['active'])?1:0,(int)($_POST['sort_order']??0)]);}elseif($action==='criterion'){$id=(int)($_POST['id']??0);$text=trim($_POST['criteria_text']??'');if($id)Database::execute('UPDATE hr_kpi_criteria SET criteria_text=?,criteria_hash=?,category=?,weight=?,max_score=?,sort_order=?,active=?,updated_at=NOW() WHERE id=?',[$text,hash('sha256',mb_strtolower($text,'UTF-8')),trim($_POST['category']??''),max(.01,(float)$_POST['weight']),max(.01,(float)$_POST['max_score']),(int)$_POST['sort_order'],isset($_POST['active'])?1:0,$id]);else Database::execute('INSERT INTO hr_kpi_criteria(template_id,criteria_text,criteria_hash,category,weight,max_score,sort_order,active,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,NOW(),NOW())',[(int)$_POST['template_id'],$text,hash('sha256',mb_strtolower($text,'UTF-8')),trim($_POST['category']??''),max(.01,(float)$_POST['weight']),max(.01,(float)$_POST['max_score']),(int)$_POST['sort_order'],isset($_POST['active'])?1:0]);}flash('عملیات با موفقیت انجام شد.');}catch(Throwable $e){error_log('HR KPI template save: '.$e->getMessage());flash('خطا در ذخیره‌سازی اطلاعات. لطفاً مجدد تلاش کنید.','danger');}redirect('/admin/hr-kpi-templates.php');}
$templates=Database::fetchAll('SELECT t.*,(SELECT COUNT(*) FROM hr_kpi_criteria c WHERE c.template_id=t.id) criteria_count FROM hr_kpi_templates t ORDER BY sort_order,id');$selected=(int)($_GET['template_id']??($templates[0]['id']??0));$criteria=$selected?Database::fetchAll('SELECT * FROM hr_kpi_criteria WHERE template_id=? ORDER BY sort_order,id',[$selected]):[];$editTemplate=isset($_GET['edit_template'])?Database::fetch('SELECT * FROM hr_kpi_templates WHERE id=?',[(int)$_GET['edit_template']]):null;$editCriterion=isset($_GET['edit_criterion'])?Database::fetch('SELECT * FROM hr_kpi_criteria WHERE id=? AND template_id=?',[(int)$_GET['edit_criterion'],$selected]):null;require __DIR__.'/../views/partials/admin-header.php';?>
<section class="card admin-form"><h2><?=$editTemplate?'ویرایش قالب':'قالب جدید'?></h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="template"><input type="hidden" name="id" value="<?=e($editTemplate['id']??'')?>"><div class="grid grid-3"><label class="form-field"><span>عنوان</span><input name="title" value="<?=e($editTemplate['title']??'')?>" required></label><label class="form-field"><span>کد</span><input dir="ltr" name="code" value="<?=e($editTemplate['code']??'')?>" required <?=$editTemplate?'readonly':''?>></label><label class="form-field"><span>کلید نقش</span><input dir="ltr" name="role_key" value="<?=e($editTemplate['role_key']??'')?>"></label><label class="form-field"><span>واحد</span><input name="department" value="<?=e($editTemplate['department']??'')?>"></label><label class="form-field"><span>دسته</span><input name="category" value="<?=e($editTemplate['category']??'')?>"></label><label class="form-field"><span>ترتیب</span><input type="number" name="sort_order" value="<?=e($editTemplate['sort_order']??100)?>"></label><label class="checkbox-item"><input type="checkbox" name="active" <?=!$editTemplate||$editTemplate['active']?'checked':''?>> فعال</label></div><div class="form-actions"><button class="btn btn-primary">ذخیره</button><?php if($editTemplate):?><a class="btn" href="/admin/hr-kpi-templates.php?template_id=<?=$selected?>">انصراف</a><?php endif?></div></form></section>
<div class="grid grid-2"><section class="card"><h2>قالب‌ها</h2><div class="table-wrap"><table><thead><tr><th>عنوان</th><th>کد</th><th>معیار</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($templates as $t):?><tr><td><a href="?template_id=<?=$t['id']?>"><?=e($t['title'])?></a></td><td><code><?=e($t['code'])?></code></td><td><?=e($t['criteria_count'])?></td><td><?=$t['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?template_id=<?=$t['id']?>&edit_template=<?=$t['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section><section class="card admin-form"><h2><?=$editCriterion?'ویرایش معیار':'افزودن معیار'?></h2><?php if($selected):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(Auth::csrfToken())?>"><input type="hidden" name="action" value="criterion"><input type="hidden" name="id" value="<?=e($editCriterion['id']??'')?>"><input type="hidden" name="template_id" value="<?=$selected?>"><label class="form-field"><span>متن معیار</span><textarea name="criteria_text" required><?=e($editCriterion['criteria_text']??'')?></textarea></label><div class="grid grid-3"><label class="form-field"><span>وزن</span><input type="number" step=".01" name="weight" value="<?=e($editCriterion['weight']??1)?>"></label><label class="form-field"><span>حداکثر امتیاز</span><input type="number" step=".01" name="max_score" value="<?=e($editCriterion['max_score']??10)?>"></label><label class="form-field"><span>ترتیب</span><input type="number" name="sort_order" value="<?=e($editCriterion['sort_order']??100)?>"></label></div><label class="checkbox-item"><input type="checkbox" name="active" <?=!$editCriterion||$editCriterion['active']?'checked':''?>> فعال</label><button class="btn btn-primary">ذخیره</button></form><?php endif?></section></div>
<section class="card"><h2>معیارهای قالب انتخابی</h2><div class="table-wrap"><table><thead><tr><th>معیار</th><th>وزن</th><th>حداکثر</th><th>ترتیب</th><th>وضعیت</th><th></th></tr></thead><tbody><?php foreach($criteria as $c):?><tr><td><?=e($c['criteria_text'])?></td><td><?=e($c['weight'])?></td><td><?=e($c['max_score'])?></td><td><?=e($c['sort_order'])?></td><td><?=$c['active']?'فعال':'غیرفعال'?></td><td><a class="btn btn-small" href="?template_id=<?=$selected?>&edit_criterion=<?=$c['id']?>">ویرایش</a></td></tr><?php endforeach?></tbody></table></div></section>
</section></main></div><script src="/assets/js/app.js"></script></body></html>
